B.a9p=new A.K6("First sentence","\u0623\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u064e\u0646\u0652 \u0644\u064e\u0627 \u0625\u0650\u0644\u0670\u0647\u064e \u0625\u0650\u0644\u064e\u0651\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064f","Ashhadu an la ilaha illa Allah","I bear witness that there is no god but Allah.")
B.a9q=new A.K6("Second sentence","\u0648\u064e\u0623\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u064e\u0646\u064e\u0651 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064b\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650","Wa ashhadu anna Muhammadan rasul Allah","And I bear witness that Muhammad is the messenger of Allah.")
B.vL=s([B.a9p,B.a9q],t.Ax)
